<script setup>
import StateHint from './StateHint.vue'
import RouteMapCard from './RouteMapCard.vue'
import OIcon from './OutingIcon.vue';import {ref,computed,onMounted,onUnmounted} from 'vue';import {onShow} from '@dcloudio/uni-app';import {state,readState,writeState,removeState,refreshState,tourView,finishTour,serverFinishTour,serverAdjust,serverProgressTick,syncServer,serverCreateHelp,serverLoadHelp,createHelp,helpLabels,navigate,adjustTour,confirm} from './app-state.js';import {routes,facilities as facilityData,clockAt} from './travel-data.js';const props=defineProps({mode:String});let clockTimer,helpTimer;onMounted(()=>{clockTimer=setInterval(()=>{refreshState();serverProgressTick()},30000);if(props.mode==='help')helpTimer=setInterval(()=>{if(!state.help||state.help.status!=='RESOLVED')serverLoadHelp()},2000)});onUnmounted(()=>{clearInterval(clockTimer);clearInterval(helpTimer)});const category=ref('厕所'),search=ref('');const tour=computed(tourView),adjusted=computed(()=>!!tour.value?.adjusted),route=computed(()=>tour.value?.routeData.name||'尚未开始游览');const shortRoute=computed(()=>routes.filter(r=>r.routeId&&tour.value&&r.routeId!==tour.value.routeId).sort((a,b)=>a.minutes-b.minutes)[0]||routes[0]);onShow(()=>{refreshState();syncServer({force:true});serverProgressTick();if(props.mode==='help')serverLoadHelp();if(props.mode==='facilities'){category.value=readState('facility-category')||'厕所';removeState('facility-category')}});const title=computed(()=>({ongoing:'游览进行中',facilities:'设施查询',fatigue:'我有点累了',help:'求助进度'}[props.mode]));const lists=computed(()=>(facilityData[category.value]||[]).filter(x=>x.join('').includes(search.value)));
const remainingText=computed(()=>tour.value?.remainingMin==null?'暂无法估算':tour.value.remainingMin+' 分钟')
function finish(){if(!tour.value)return note('尚未开始游览。');confirm('结束本次游览','确认已完成游览？结束后会保存到游览记录。',async()=>{if(await serverFinishTour())navigate('trip-complete')})}function facilities(c){writeState('facility-category',c);go('facilities')}function go(n){navigate('tour-'+n)}function back(){if(getCurrentPages().length>1)uni.navigateBack();else uni.reLaunch({url:'/pages/home'})}function note(content){uni.showModal({title:'演示说明',content,showCancel:false})}function help(){confirm('发起求助','求助会发到景区服务中心，工作人员接单后为您提供协助。是否继续？',async()=>{const h=await serverCreateHelp();if(h)go('help')})}function adjust(){if(!tour.value)return note('尚未开始游览。');const target=shortRoute.value;confirm('确认调整路线','原计划剩余 '+remainingText.value+' → 调整后走「'+(target?.name||'更短的路线')+'」约'+(target?.minutes||0)+'分钟',async()=>{if(await serverAdjust('return'))uni.redirectTo({url:'/pages/tour-ongoing'})})}
function updateReason(){uni.showModal({title:'更新求助信息',editable:true,placeholderText:state.help?.reason||'补充求助原因',success:r=>{if(r.confirm&&r.content?.trim()){writeState('help',{...state.help,reason:r.content.trim(),updatedAt:Date.now()});writeState('help-events',state['help-events'].map(h=>h.id===state.help.id?state.help:h))}}})}
const helpStages=computed(()=>{
  const h=state.help
  if(!h)return []
  if(h.backend&&Array.isArray(h.stages))return h.stages
  const timeline=h.timeline||[]
  const level=h.status==='RESOLVED'?3:h.status==='ACKNOWLEDGED'?(timeline.some(e=>e.label.includes('处理中'))?2:1):0
  return ['已发出','已接单','处理中','已解决'].map((label,i)=>{
    const e=timeline.find(x=>x.label.includes(label))
    return {label,done:i<=level,time:e?new Date(e.time).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}):'待更新',body:['您的求助信息已发出。','工作人员受理后为您提供协助。','接单后由工作人员更新进度。','问题解决后将为您更新状态。'][i]}
  })
})
function retryServer(){syncServer({force:true})}
</script>
<template><view class="outing" :class="mode"><image class="outing-mark" src="/static/logo.svg" mode="aspectFit"/><view class="outing-header"><button aria-label="返回" @click="back"><OIcon name="back"/></button><text>{{title}}</text></view><view class="outing-subtitle"><text>清风园{{['fatigue','help'].includes(mode)?' · '+route:''}}</text><button v-if="mode==='ongoing'" class="outline" @click="note('语音服务尚未接入，可先阅读页面提示。')"><OIcon name="speaker"/>语音提示</button></view>
<template v-if="mode==='ongoing'"><StateHint v-if="!tour && state.server.loading" kind="loading" title="正在同步游览…" />
<StateHint v-else-if="!tour && state.server.error" kind="offline" title="游览状态暂时不可用" :text="state.server.error" retry-text="重试" @retry="retryServer" />
<view v-else-if="!tour||tour.ended" class="o-panel"><text>暂无进行中的游览</text><button class="solid" @click="navigate('plan')">这次怎么逛</button></view><view v-if="tour" class="o-panel"><view class="outing-progress-help"><text class="o-bold">进度 {{tour.progress}}%</text><button v-if="state.help&&state.help.status!=='RESOLVED'" @click="navigate('tour-help')">{{helpLabels[state.help.status]}} ›</button></view><button class="outline" @click="navigate('tour-stops')">查看全部行程</button><view v-for="s in tour.routeData.stations" class="o-sub">{{clockAt(tour.startClock,s.at)}} · {{s.name}} · {{s.kind}}</view></view><view class="o-panel"><text class="o-heading">{{route}}</text><view class="metrics"><view><image src="/static/outing/clock-walk.png"/><view><text>已游览</text><text class="metric-value">{{tour?.elapsedMin||0}}分钟</text></view></view><view><image src="/static/outing/clock-remain.png"/><view><text>预计剩余</text><text class="metric-value">{{remainingText}}</text></view></view></view><RouteMapCard class="o-map" :tour="tour" :adjusted="adjusted"/><text v-if="adjusted" class="o-sub">已调整路线：保留已游记录，返回公园入口。</text></view><view class="o-panel fatigue-entry"><view class="fatigue-entry-icon"><OIcon name="resting"/></view><view class="fatigue-entry-text"><text class="o-bold">我累了，想休息一下</text><text class="o-sub">可以找休息点，或调整剩余路线。</text></view><button class="outline fatigue-entry-button" @click="go('fatigue')">我累了 ›</button></view><view class="o-panel next"><image src="/static/outing/next-rest.png"/><view><text class="o-bold">下一站：{{tour?.nextStop?.name||'已到最后一站'}}</text><text class="o-sub">沿当前步道继续前行。</text><button class="outline" @click="note('当前为路线示意，尚未接入真实定位与导航。')">查看怎么走 ›</button></view></view><view class="o-panel next"><image src="/static/outing/current-stop.png" mode="aspectFill"/><view><text class="o-bold">正在游览：{{tour?.currentStop?.name||'尚未开始'}}</text><text class="o-sub">沿湖慢走，欣赏湖景与绿荫，感受公园的宁静与自然。</text><button class="o-link" @click="navigate('spot')"><OIcon name="speaker"/>听景点讲解</button></view></view><view class="o-panel"><text class="o-heading">其他便捷服务</text><view class="facility-shortcuts"><button v-for="x in [['people','找厕所'],['seat','找休息点'],['exit','找出口']]" :key="x[1]" @click="facilities(x[1]==='找厕所'?'厕所':x[1]==='找休息点'?'休息点':'出口')"><image :src="'/static/travel/'+x[0]+'.png'"/><text>{{x[1]}}</text><text class="shortcut-sub">{{x[1]==='找厕所'?'沿途设有'+(tour?.routeData.toilets||0)+'处':x[1]==='找休息点'?'沿途设有'+(tour?.routeData.seats||0)+'处':'返回公园入口'}}</text></button></view></view><view class="o-notice">演示数据 · 地图与设施为示意。结束游览前会请您确认。</view><view class="o-footer"><button class="outline finish-action" @click="finish"><OIcon name="flag"/>结束游览</button><button class="solid" @click="help"><OIcon name="people"/>找人帮忙</button></view></template>
<template v-else-if="mode==='facilities'"><view class="o-panel search-panel"><view class="facility-search"><OIcon name="search"/><input v-model="search" placeholder="搜索设施" aria-label="搜索设施"/></view><view class="categories"><button v-for="c in ['厕所','休息点','出口','医务室']" :key="c" :class="{active:category===c}" @click="category=c"><OIcon :name="({厕所:'people',休息点:'seat',出口:'exit',医务室:'medical'})[c]"/>{{c}}</button></view></view><view class="o-panel"><view class="location-label"><OIcon name="pin"/><text class="o-bold">演示位置：{{tour?.currentStop?.name||'尚未开始'}}</text></view><image class="o-map" src="/static/outing/facilities.jpg" mode="widthFix"/></view><view class="o-panel"><text class="o-heading">附近的{{category}}</text><view v-for="(item,i) in lists" :key="item[0]" class="facility-result" :class="{nearest:i===0}"><image class="result-icon" :src="'/static/travel/'+(category==='厕所'?'people':category==='休息点'?'seat':'exit')+'.png'"/><text class="o-bold">{{item[0]}} <text v-if="i===0" class="badge">较近</text></text><text class="o-sub">{{item[1]}}</text><text class="o-sub">{{category==='厕所'?'平缓步道 · 设有无障碍卫生间':'设施信息以现场标识为准'}}</text><button :class="i===0?'solid':'outline'" @click="note('已选择'+item[0]+'。当前为模拟设施数据，不提供实时导航。')">{{i===0?'带我过去':'查看路线'}}</button></view><text v-if="!lists.length" class="o-sub">没有找到相关设施，请换个关键词。</text></view><view class="o-notice">设施与距离为示意，请以现场标识为准。</view><view class="o-footer"><button class="outline" @click="help"><OIcon name="headset"/>找不到？联系工作人员</button></view></template>
<template v-else-if="mode==='fatigue'"><view class="o-panel fatigue-greeting"><OIcon name="smile"/><view><text class="o-bold">您先休息一下，</text><text>我们把接下来的路走得轻松些。</text></view></view><view class="o-panel fatigue-rest"><image src="/static/travel/seat.png"/><view><text class="o-bold">最近休息点：林荫休息点</text><text class="o-sub">约80米 · 步行约2分钟</text></view><button class="outline" @click="facilities('休息点')">先去休息</button></view><view class="o-panel"><text class="o-heading">建议缩短剩余路线</text><text class="o-sub">保留已游记录，跳过后续景点，返回公园入口。</text><image class="o-map" src="/static/outing/fatigue.jpg" mode="widthFix"/><view class="map-legend"><view><text class="line-swatch"/>已走（约{{tour?.elapsedMin||0}}分钟）</view><view><text class="line-swatch dashed"/>建议路线<br/>（返回入口）</view><view><text class="line-swatch gray"/>原剩余路线<br/>（{{remainingText}}）</view></view><view class="comparison"><view><text class="o-bold">原计划</text><text class="o-sub">按原路线继续游览</text><view class="compare-metric"><OIcon name="clock"/><text>剩余{{remainingText}}</text></view><view class="compare-metric"><OIcon name="mountain"/><text class="o-sub">剩余距离为路线示意</text></view><view class="compare-metric"><OIcon name="flag"/><text class="o-sub">{{tour?.nextStop?.name||'行程结束'}}</text></view></view><view><text class="o-bold">调整后</text><text class="o-sub">返回公园入口</text><view class="compare-metric"><OIcon name="clock"/><text>剩余约{{shortRoute?.minutes||0}}分钟</text></view><view class="compare-metric"><OIcon name="mountain"/><text class="o-sub">路线距离为演示估计</text></view><view class="compare-metric"><OIcon name="flag"/><text class="o-sub">直接返回入口</text></view></view></view><view class="o-notice blue"><OIcon name="info"/>确认后才会更换路线。</view></view><view class="o-panel o-options"><button @click="back"><OIcon name="seat"/><view><text class="o-bold">只休息，暂不改路线</text><text class="o-sub">在休息后继续按原路线游览。</text></view><text>›</text></button><button @click="help"><OIcon name="person"/><view><text class="o-bold">需要帮助？联系工作人员</text><text class="o-sub">如需协助，可联系现场工作人员。</text></view><text>›</text></button></view><view class="o-footer"><button class="outline" @click="back">保留原路线</button><button class="solid" @click="adjust">确认调整路线</button></view></template>
<template v-else><template v-if="state.help"><view class="o-panel"><view class="staff-heading"><image src="/static/outing/staff.png"/><view><text class="help-title">{{helpLabels[state.help.status]}}</text><text class="o-sub">{{state.help.status==='OPEN'?'请在安全位置等候工作人员受理':state.help.status==='ACKNOWLEDGED'?'工作人员已受理，请留意处理进度':'本次求助已处理完成'}}</text></view></view><view class="timeline"><view v-for="(e,i) in helpStages" :key="e.label" class="timeline-row" :class="{pending:!e.done}"><text class="step">{{e.done&&i===0?'✓':i+1}}</text><view><text class="o-bold">{{e.label}}</text><text class="o-sub">{{e.time}}</text></view><text class="timeline-detail">{{e.body}}</text></view></view></view><view class="o-panel"><text class="o-heading">本次求助</text><view class="help-row"><OIcon name="file"/><view><text class="o-bold">求助原因</text><text class="o-sub">{{state.help.reason}}</text></view></view><view class="help-row"><OIcon name="pin"/><view><text class="o-bold">位置</text><text class="o-sub">{{state.help.location.replace(/（演示）/g,'')}}</text></view></view><view class="help-row"><OIcon name="phone"/><view><text class="o-bold">联系方式</text><text class="o-sub">{{state.profile.emergencyContact.phone||'暂未添加联系电话'}}</text></view></view><image class="o-map" src="/static/outing/help.jpg" mode="widthFix"/></view><view class="o-panel"><text class="o-heading">家属通知</text><text class="o-sub">{{state.help.notifications.length?state.help.notifications.map(n=>n.to+'：'+n.body).join('；'):'未共享求助通知'}}</text><button class="outline" @click="navigate('family')">查看授权</button><view class="o-footer"><button v-if="!state.help||!state.help.backend" class="outline" @click="updateReason">更新求助信息</button><button class="solid" @click="note('尚未接入工作人员联系电话，未实际联系。')">联系工作人员</button></view></view></template><view v-else class="o-panel"><text>暂无求助</text><button class="solid" @click="help">发起求助</button></view></template>
</view></template>
<style src="./outing.css"></style>
<style>
.outing-progress-help{display:flex;align-items:center;justify-content:space-between;gap:8px;min-width:0}.outing .outing-progress-help>button{flex-shrink:0;width:auto;max-width:65%;margin:0;padding:6px 12px;min-height:0;line-height:1.5;font-size:14px;border-radius:999px;color:#006aff;background:#edf5ff}
</style>

<style scoped>
:deep(.state-hint){min-width:0;max-width:100%;box-sizing:border-box;overflow-wrap:anywhere}
:deep(.state-hint .state-title),:deep(.state-hint .state-text){max-width:100%}
</style>
